var cards = vars.re_cards || [];
var ids = {};
cards.forEach(function (c) { ids[String(c.Id)] = true; });
var pool = cards.filter(function (c) { return !(c.TemplateId && ids[String(c.TemplateId)]); })
                .map(function (c) { return { id: String(c.Id), name: c.Name }; });
return { re_pool: pool, re_count: pool.length };
